fallos = []
for fich, viejo, nuevo in FIXES:
    p = os.path.join(GAME, fich)
    txt = open(p, encoding="utf-8").read()
    n = txt.count(viejo)
    if n == 0:
        fallos.append((fich, viejo[:70]))
        continue
    open(p, "w", encoding="utf-8").write(txt.replace(viejo, nuevo))
    if n > 1:
        print(f"{fich}: {n}x {viejo[:60]}")
print(f"Aplicados: {len(FIXES)-len(fallos)}/{len(FIXES)}  Fallos: {len(fallos)}")
for f, v in fallos:
    print(f"FALLO {f}: {v}")
